    description:
      'A basic page structure using header, navigation, main content, sections, and footer.',
    example:
      '<body>\n <header>\n    <h1>Page Title</h1>\n  </header>\n\n  <nav aria-label="Main navigation">\n    <a href="/">Home</a>\n    <a href="/about">About</a>\n  </nav>\n\n  <main>\n    <section>\n      <h2>Featured Content</h2>\n      <p>Page content...</p>\n    </section>\n  </main>\n\n  <footer>\n    <p>Copyright 2026</p>\n  </footer>\n</body>',
    href: '/references/patterns/patterns.html#semantic-page',
